<script setup lang="ts">
import { ref } from 'vue'
import { IconAdjustmentsHorizontal, IconSearch, IconRefresh, IconChevronDown } from '@tabler/icons-vue'
import type { useAnimeNaming } from '../composables/useAnimeNaming'
const props = defineProps<{ naming: ReturnType<typeof useAnimeNaming>; disabled: boolean }>()
const manualID = ref('')
function loadID() { if (/^[1-9]\d*$/.test(manualID.value.trim())) void props.naming.load(manualID.value.trim()) }
</script>
<template>
  <section class="ae-naming-target" aria-label="TMDB 命名目标" :aria-busy="naming.busy.value || naming.searching.value">
    <div class="ae-naming-heading"><div><span class="ae-label">整理命名目标</span><h3 v-if="naming.target.value">{{ naming.target.value.title }} <small>({{ naming.target.value.year }}) · TMDB {{ naming.target.value.tmdbId }}</small></h3><p v-else class="ae-note">{{ naming.searching.value || naming.busy.value ? '正在匹配 TMDB 作品与目标季…' : '关联 TMDB 后，按对应季集标准命名整理。' }}</p></div><button type="button" class="ae-button" :disabled="disabled || naming.busy.value" :aria-expanded="naming.picker.value" @click="naming.picker.value = !naming.picker.value"><IconAdjustmentsHorizontal :size="16" aria-hidden="true" />{{ naming.target.value ? '更换目标' : '关联 TMDB' }}</button></div>
    <div v-if="naming.target.value" class="ae-target-season"><label class="ae-label" for="anime-target-season">目标季</label><select id="anime-target-season" :value="naming.target.value.season" :disabled="disabled || naming.busy.value" @change="naming.load(naming.target.value!.tmdbId, Number(($event.target as HTMLSelectElement).value), naming.target.value!.groupId)"><option v-for="season in naming.target.value.seasons" :key="season.number" :value="season.number">{{ season.name || `第 ${season.number} 季` }} · {{ season.episodeCount }} 集{{ season.date ? ` · ${season.date}` : '' }}</option></select><span class="ae-note">{{ naming.target.value.groupName }} · 请核对推荐季与下方实际编号</span></div>
    <div v-if="naming.picker.value" class="ae-target-picker">
      <form class="ae-search" @submit.prevent="naming.search()"><input v-model="naming.keyword.value" aria-label="搜索 TMDB 作品" maxlength="128" placeholder="输入作品名称" :disabled="disabled" /><button type="submit" class="ae-button" :disabled="disabled || naming.searching.value"><IconSearch :size="16" aria-hidden="true" />搜索</button></form>
      <div class="ae-target-candidates"><button v-for="item in naming.candidates.value" :key="item.id" type="button" :disabled="disabled || naming.busy.value" @click="naming.load(String(item.id))"><strong>{{ item.title }}</strong><small>{{ item.date?.slice(0, 4) || '年份待定' }} · TMDB {{ item.id }}</small></button></div>
      <p v-if="!naming.searching.value && !naming.candidates.value.length" class="ae-note">可搜索作品名称，或直接填写已知 TMDB ID。</p>
      <form class="ae-search" @submit.prevent="loadID"><input v-model="manualID" inputmode="numeric" aria-label="TMDB 作品 ID" placeholder="TMDB 作品 ID" :disabled="disabled" /><button type="submit" class="ae-button" :disabled="disabled || naming.busy.value || !/^[1-9]\d*$/.test(manualID.trim())">使用此 ID</button></form>
    </div>
    <p v-if="naming.error.value" class="ae-error" role="status">{{ naming.error.value }}<span v-if="naming.target.value">，当前目标已保留。</span></p>
    <details v-if="naming.target.value" class="ae-advanced" @toggle="($event.target as HTMLDetailsElement).open && naming.readGroups()"><summary>目标编排选项<IconChevronDown :size="15" aria-hidden="true" /></summary><div class="ae-field"><label class="ae-label" for="anime-target-group">剧集编排</label><select id="anime-target-group" :value="naming.target.value.groupId" :disabled="disabled || naming.busy.value" @change="naming.load(naming.target.value!.tmdbId, undefined, ($event.target as HTMLSelectElement).value)"><option value="">TMDB 默认季集</option><option v-if="naming.target.value.groupId && !naming.groups.value.some(g => g.id === naming.target.value!.groupId)" :value="naming.target.value.groupId">{{ naming.target.value.groupName }}</option><option v-for="group in naming.groups.value" :key="group.id" :value="group.id">{{ group.name }}</option></select></div><button type="button" class="ae-link" :disabled="disabled || naming.busy.value" @click="naming.load(naming.target.value!.tmdbId, naming.target.value!.season, naming.target.value!.groupId)"><IconRefresh :size="14" aria-hidden="true" />重新读取目标资料</button><p class="ae-note">编号方案仅用于本订阅，下载完成后按此方案自动整理。</p></details>
  </section>
</template>
